import './index.scss';

const Home = () => {
  return (
    <div id="home" className="container home-page">
      <div className="text-zone">
        <h1>
          Hi,
          <br />
          I'm <span className="highlight-c">Chris</span>,
          <br />
          Web Developer.
        </h1>
        <h2>FRONTEND DEVELOPER / JAVASCRIPT, HTML/CSS, REACT</h2>

        <a href="#contact" className="flat-button">
          CONTACT ME
        </a>
      </div>
    </div>
  );
};

export default Home;
